import{_ as i,o as s,c as e,ag as t}from"./chunks/framework.DoUXNnsN.js";const k=JSON.parse('{"title":"我的笔记使用说明","description":"","frontmatter":{"title":"我的笔记使用说明","aliases":["我的笔记","导入笔记","新增笔记"],"tags":["使用说明"],"status":"ai-draft","sources":["基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"90-我的笔记/使用说明.md","filePath":"90-我的笔记/使用说明.md"}'),l={name:"90-我的笔记/使用说明.md"};function o(n,a,d,r,h,c){return s(),e("div",null,[...a[0]||(a[0]=[t(`<blockquote><p>这个文件夹是<strong>你自己的地盘</strong>。我（Claude）不会改写这里的任何文件，只会在你要求时帮你整理。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><code>90-我的笔记/</code> 用来放你自己写的、导入的笔记。它们和我写的词条放在同一个知识库里，用同一个网站查看、同一个搜索框搜索，但内容永远由你说了算。</p><h2 id="怎么新增一条笔记" tabindex="-1">怎么新增一条笔记 <a class="header-anchor" href="#怎么新增一条笔记" aria-label="Permalink to &quot;怎么新增一条笔记&quot;">​</a></h2><ol><li>在 <code>kb\\90-我的笔记\\</code> 里新建一个 <code>.md</code> 文件，文件名就是笔记名，例如 <code>今天学的SQL.md</code>。</li><li>文件开头可以什么都不写，直接写正文；想让搜索和标签更好用，可以加一小段头部：</li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">今天学的 SQL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tags</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">笔记</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SQL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><ol start="3"><li>保存。网站在启动状态下会自动刷新；但<strong>左侧目录是启动时生成的</strong>，新增文件后要关掉再重新双击 <code>启动知识库.bat</code>。</li><li>想引用知识库里的词条，写 <code>[[词条名]]</code>，例如 <code>[[索引]]</code>、<code>[[SQL基础查询]]</code>，网站会变成链接。</li></ol><h2 id="怎么导入已有的笔记" tabindex="-1">怎么导入已有的笔记 <a class="header-anchor" href="#怎么导入已有的笔记" aria-label="Permalink to &quot;怎么导入已有的笔记&quot;">​</a></h2><ul><li><strong>Markdown (.md)</strong>：直接复制进 <code>90-我的笔记\\</code>（可以建子文件夹分类）。</li><li><strong>Word (.docx) / PDF</strong>：告诉我文件在哪，我帮你转成 Markdown 放进来。</li><li><strong>网页剪藏、零散想法</strong>：先丢进 <code>00-收件箱\\</code>，需要整理时告诉我，我帮你归类成词条或放到这里。收件箱不会出现在网站上。</li></ul><h2 id="想把笔记升级成正式词条" tabindex="-1">想把笔记升级成正式词条 <a class="header-anchor" href="#想把笔记升级成正式词条" aria-label="Permalink to &quot;想把笔记升级成正式词条&quot;">​</a></h2><p>告诉我&quot;把 XX 笔记整理成词条&quot;，我会参考你的笔记补全成正式词条，放进对应分类，原笔记保留不动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>你的笔记放 <code>90-我的笔记\\</code>，我不改。</li><li>新增后重启网站才能在左侧目录看到。</li><li>用 <code>[[词条名]]</code> 可以链接到知识库里的词条。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/">索引</a>、<a href="/Encyclopedia/术语表">术语表</a>、<a href="/Encyclopedia/待核对清单">待核对清单</a></p>`,15)])])}const u=i(l,[["render",o]]);export{k as __pageData,u as default};
